import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: {(project_basename, framework, package_id): version}
def build_lookup(data):
    lookup = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                lookup[(name, fw['framework'], pkg['id'])] = pkg['resolvedVersion']
    return lookup

b = build_lookup(baseline)
a = build_lookup(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))

changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv != av:
        changes.append((k[0], k[1], k[2], bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((k[0], k[1], k[2], bv))

if changes:
    print('CHANGES:')
    print(f'{\"Project\":<15} {\"Framework\":<10} {\"Package\":<45} {\"Before\":<10} {\"After\":<10}')
    for c in changes:
        print(f'{c[0]:<15} {c[1]:<10} {c[2]:<45} {c[3]:<10} {c[4]:<10}')
else:
    print('No changes detected')

print()
print(f'UNCHANGED: {len(unchanged)} package-framework entries resolve identically')
"

